openai_raw_latex:
\begin{theorem}\label{strongmg} 
For any mixed graph $G=(V,E,A)$ and positive integer $k$, $(-1)^{|V|} \widehat{\chi}_G(-k)$ equals the number of $k$-colorings of $G$, each counted with multiplicity equal to the number of compatible acyclic orientations of~$G$.
\end{theorem}

anthropic_raw_latex:
\begin{lemma}\label{phisum}
If $G$ is an acyclic mixed graph, then $\chi_G(k) = \displaystyle\sum_{i=1}^m \phi_{G_i}(k) \, .$
\end{lemma}

openai_raw_latex:
\begin{theorem}\label{main}
For any acyclic mixed graph $G=(V,E,A)$ and positive integer $k$, $(-1)^{|V|} {\chi}_G(-k)$ equals the number of $k$-colorings of $G$, each counted with multiplicity equal to the number of intercompatible acyclic orientations of~$G$.
\end{theorem}

anthropic_raw_latex:
\begin{lemma}\label{labeling}
For each $G_i$, there exists an $\omega_i$-labeling of $P_i$ such that $$\phi_{G_i}(k) = \Omega_{P_i,\omega_i}(k) \, .$$ Moreover, $\Omega_{P_i,\overline{\omega}_i}(k)$ is the number of $k$-colorings intercompatible with $G_i$.
\end{lemma}

\begin{proposition}\label{cycle_contract_lemma}
If $G$ is a strongly connected directed graph, then $\chi_G(k) = k$.
\end{proposition}

\begin{proposition}\label{subcontract}
Let $G$ be a mixed graph and $S$ be a strongly connected directed subgraph of $G$. Then $\chi_G(k)=\chi_{G/S}(k)$. 
\end{proposition}
